        $('.field-error').empty();
        $('.input-error').removeClass('input-error');
    }

function validateDoctor(data, isInsert) {
        clearValidation();
        var valid = true;
        var required = [
            ['fname', data.firstname, 'First name is required.'],
            ['lname', data.lastname, 'Last name is required.'],
            ['clinicname', data.clinic, 'Clinic name is required.'],
            ['address', data.address, 'Address is required.'],
            ['area', data.area, 'Area is required.'],
            ['source', data.source !== '0', 'Source type is required.']
        ];

        $.each(required, function (_, item) {
            if (!item[1]) {
