        }

        if (!data.gender) {
            $('#err-gender').text('Gender is required.');
            valid = false;
        }

        if (!/^\d{10}$/.test(data.mobileno)) {
            $('#err-mobile').text(data.mobileno ? 'Enter a 10-digit mobile number.' : 'Mobile number is required.');
            $('#txtmobile').addClass('input-error');
            valid = false;
        }

        if (data.alternateno && !/^\d{10}$/.test(data.alternateno)) {
            $('#err-altmobile').text('Enter a 10-digit alternate number.');
            $('#txtalternateno').addClass('input-error');
            valid = false;
        }

        // Doctor Type is only shown for Network Doctors (source 1). The select's
        // placeholder value is the string '0', which is truthy, so test it explicitly.
        if (data.source === '1' && (!data.networkprog || data.networkprog === '0')) {
            $('#err-networkingprog').text('Doctor type is required.');
