        if (isInsert && !formValue('#txtNewPassword')) {
            $('#err-password').text('Password is required.');
            $('#txtNewPassword').addClass('input-error');
            valid = false;
        }

        // Bank details are optional end-to-end — these checks only fire when
        // the person actually typed something, per the spec ("Account Number
        // - optional", "IFSC - optional").
        if (data.accountNumber && !/^\d{6,20}$/.test(data.accountNumber)) {
            $('#err-accountnumber').text('Account number should be 6-20 digits.');
            $('#txtAccountNumber').addClass('input-error');
