function saveDoctor(action) {
        var data = readForm();
        var isInsert = action === 'I';
        if (!validateDoctor(data, isInsert)) { return; }

        data.action = action;
        data.id = isInsert ? '' : formValue('#hdnid');
        data.newPassword = isInsert
            ? formValue('#txtNewPassword')
            : ($('#chkChangePassword').is(':checked') ? formValue('#txtChangePassword') : '');

        if (!isInsert && $('#chkChangePassword').is(':checked') && !data.newPassword) {
            showToast('Enter a new password or clear Change password.', true);
            $('#txtChangePassword').trigger('focus');
            return;
        }

        setSaving(true);
        post('Save', data)
            .done(function (response) {
                switch (response.d) {
                    case '1':
                        showToast(isInsert ? 'Doctor added successfully.' : 'Doctor updated successfully.', false);
                        resetForm();
                        reloadDoctorGrid();
                        break;
                    case 'EXIST':
                        showToast('Another doctor already has this mobile number.', true);
                        break;
                    case 'INVALIDBANK':
                        showToast('Bank name contains characters that are not allowed.', true);
                        break;
                    case 'NOTFOUND':
                        showToast('This doctor no longer exists. The list has been refreshed.', true);
                        resetForm();
                        reloadDoctorGrid();
                        break;
                    default:
                        showToast('Unable to save the doctor.', true);
                        break;
                }
            })
            .fail(function () { showToast('Server error. Please try again.', true); })
            .always(function () { setSaving(false); });
    }

function saveColumnPrefs() {
        var visible = [], known = [];
        grid.columns().every(function () {
            var name = this.settings()[0].aoColumns[this.index()].sName;
            if ($(this.header()).hasClass('noVis')) { return; }
            known.push(name);
            if (this.visible()) { visible.push(name); }
        });
        try { window.localStorage.setItem(COLUMN_STORE_KEY, JSON.stringify({ visible: visible, known: known })); } catch (e) { /* storage unavailable: choice just isn't remembered */ }
    }
